/**
 * @fileoverview Reference-data API client — customers, sites, assets, technicians,
 * skills, certification types and technician certifications.
 *
 * All functions delegate to the platform HTTP client which attaches the Bearer
 * token and normalises errors into ClientError. Every mutating call includes an
 * Idempotency-Key generated by the HTTP layer.
 *
 * @module api/refdata
 */
import { get, post, put } from './http.js'
import { toQueryString, buildPageQuery } from './pagination.js'

// ── Customers ────────────────────────────────────────────────────────────────

/**
 * @param {{ page?: number, size?: number, sort?: string, q?: string, signal?: AbortSignal }} opts
 * @returns {Promise<import('./pagination.js').PagedResponse>}
 */
export function listCustomers({ page = 0, size = 20, sort, q, signal } = {}) {
  const pq = buildPageQuery({ page, size, sort })
  const qs = toQueryString(pq) + (q ? `&q=${encodeURIComponent(q)}` : '')
  return get(`/customers?${qs}`, { signal })
}

/**
 * @param {{ name: string, reference?: string }} body
 */
export function createCustomer(body) {
  return post('/customers', { body: JSON.stringify(body) })
}

/**
 * @param {string} id
 * @param {{ name: string, reference?: string }} body
 */
export function updateCustomer(id, body) {
  return put(`/customers/${id}`, { body: JSON.stringify(body) })
}

