/**
 * Batch upsert skills for a technician.
 * @param {string} technicianId
 * @param {{ items: Array<{ skillCode: string, proficiency: string, yearsExperience?: number }> }} body
 * @param {string} idempotencyKey
 */
export function upsertTechnicianSkills(technicianId, body, idempotencyKey) {
  return put(`/technicians/${technicianId}/skills`, {
    body: JSON.stringify(body),
    headers: { 'Idempotency-Key': idempotencyKey },
  })
}

