// ── Technician certifications ────────────────────────────────────────────────

/**
 * @param {string} technicianId
 * @param {{ atDate?: string, signal?: AbortSignal }} opts
 */
export function listTechnicianCertifications(technicianId, { atDate, signal } = {}) {
  const qs = atDate ? `?atDate=${encodeURIComponent(atDate)}` : ''
  return get(`/technicians/${technicianId}/certifications${qs}`, { signal })
}

/**
 * Batch upsert certifications for a technician.
 * @param {string} technicianId
 * @param {{ items: Array<{ typeCode: string, certificateReference?: string, issuedOn: string, expiresOn?: string, issuingBody?: string }> }} body
 * @param {string} idempotencyKey
 */
export function upsertTechnicianCertifications(technicianId, body, idempotencyKey) {
  return put(`/technicians/${technicianId}/certifications`, {
    body: JSON.stringify(body),
    headers: { 'Idempotency-Key': idempotencyKey },
  })
}

/**
 * GET eligible technician IDs by required certification types.
 * @param {{ requiredTypeCodes: string[], atDate?: string, signal?: AbortSignal }} opts
 */
export function listEligibleTechnicians({ requiredTypeCodes, atDate, signal } = {}) {
  const qs = new URLSearchParams()
  requiredTypeCodes.forEach(c => qs.append('requiredTypeCodes', c))
  if (atDate) qs.set('atDate', atDate)
  return get(`/technicians/eligible?${qs.toString()}`, { signal })
}
